pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 priceWad) public {
        // priceWad is the raw int256 price we expect the oracle to return
        // We bound it to a range that excludes the bug's fixed zero, keeping the domain wide.
        // Zero is excluded because the bug returns zero, and we need the correct result to be non-zero to detect the difference.
        priceWad = uint256(bound(int256(priceWad), 1, type(int128).max));

        // Deploy a mock oracle that always returns this price when currentVersion() is called.
        MockOracle oracle = new MockOracle(int256(priceWad));

        // Deploy a mock payoff definition that uses the PASSTHROUGH type, so the transformed price equals the raw oracle price.
        bytes30 data;
        // PASSTHROUGH = 0, direction doesn't matter for passthrough
        PayoffDefinition memory payoffDef = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(0),
            PayoffDefinitionLib.PayoffDirection(0),
            data
        );

        C.ProductInfo memory info = C.ProductInfo({
            name: "Test Product",
            symbol: "TP",
            payoffDefinition: payoffDef,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Initialize C. We need to be the controller (msg.sender) for initialization.
        // We just prank ourselves; the constructor of C sets up the controller contract check.
        // To bypass the controller check, we deploy a mock controller that returns true for isProduct.
        // But to keep it simple: we can't easily mock the controller without cheatcodes.
        // The test must use only allowed cheatcodes: vm.prank, vm.deal, etc.
        // We can't mock the controller's isProduct or coordinatorFor, so we deploy the real C and initialize it by pretending to be a valid controller.
        // Since we can't deploy a full controller, we use a trick: we create a minimal controller contract that returns the expected values.
        // Allowed vm.* methods: vm.prank, vm.deal, vm.warp, vm.roll, vm.assume, vm.bound.
        // We CAN deploy helper contracts.
        MockController controller = new MockController();
        vm.prank(address(controller));
        c.initialize(info);

        // Now call currentVersion and check the price.
        IOracleProvider.OracleVersion memory result = c.currentVersion();
        // The reference contract returns the oracle's price (since payoff is passthrough).
        // The bug always returns Fixed18.wrap(0).
        assertTrue(Fixed18.unwrap(result.price) == int256(priceWad));
    }
}

// Minimal mock Oracle that returns a configurable price
interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function currentVersion() external view returns (OracleVersion memory);
}

contract MockOracle {
    int256 public price;
    constructor(int256 _price) {
        price = _price;
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({ version: 1, timestamp: block.timestamp, price: Fixed18.wrap(price) });
    }
}

// Minimal mock Controller to pass initialization
interface IController {
    function coordinatorFor(IProduct product) external view returns (uint256);
    function owner(uint256 coordinatorId) external view returns (address);
    function isProduct(IProduct product) external view returns (bool);
    function collateral() external view returns (address);
    function incentivizer() external view returns (address);
    function minFundingFee() external view returns (UFixed18);
    function multiInvoker() external view returns (address);
    function paused() external view returns (bool);
    function productBeacon() external view returns (address);
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
    function latestVersion() external view returns (uint256);
    function pre() external view returns (PrePosition memory);
    function settle() external;
}

contract MockController is IController {
    function coordinatorFor(IProduct) external pure returns (uint256) { return 1; }
    function owner(uint256) external view returns (address) { return address(this); }
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function collateral() external view returns (address) { return address(this); }
    function incentivizer() external view returns (address) { return address(this); }
    function minFundingFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function multiInvoker() external view returns (address) { return address(this); }
    function paused() external view returns (bool) { return false; }
    function productBeacon() external view returns (address) { return address(this); }
}

// Minimal type definitions needed by the test (since we can't import full libraries)
type Fixed18 is int256;
type UFixed18 is uint256;
type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

struct PayoffDefinition {
    PayoffDefinitionLib.PayoffType payoffType;
    PayoffDefinitionLib.PayoffDirection payoffDirection;
    bytes30 data;
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH }
    enum PayoffDirection { NONE }
    function valid(PayoffDefinition memory self) internal pure returns (bool) { return true; }
    function transform(PayoffDefinition memory self, Fixed18 price) internal pure returns (Fixed18) { return price; }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

struct PrePosition {
    uint256 oracleVersion;
    Position openPosition;
    Position closePosition;
}

struct Position {
    UFixed18 maker;
    UFixed18 taker;
}

struct OracleVersion {
    uint256 version;
    uint256 timestamp;
    Fixed18 price;
}

using PayoffDefinitionLib for PayoffDefinition global;
using Fixed18Lib for Fixed18 global;

library Fixed18Lib {
    function wrap(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a); }
    function unwrap(Fixed18 a) internal pure returns (int256) { return Fixed18.unwrap(a); }
}

